// Aggregate: healthz + DB stats + disk + Hermes cron
// Dedup via staticData.lastReportTs (20h cooldown)
// Mock DB stats for testability: workflowCount=1, executionCount=0
// Real DB alternative (Execute Command node):
//   sqlite3 /home/node/.n8n/database.sqlite "SELECT count(*) FROM workflow_entity; SELECT count(*) FROM execution_entity;"
// Or host: docker run --rm -v y10hlm1fr9avvxt3asz5p0bk_n8n-data:/data alpine sqlite3 /data/database.sqlite "SELECT count(*) FROM workflow_entity"
// Disk: df -h / | awk 'NR==2{print $5}'  |  Cron: crontab -l | grep hermes
const staticData = $getWorkflowStaticData('global');
const now = Date.now();
const cooldownMs = 20 * 60 * 60 * 1000; // 20h
if (staticData.lastReportTs && (now - staticData.lastReportTs) < cooldownMs) {
  return [{ json: { skipAlert: true, reason: 'cooldown', lastReportTs: staticData.lastReportTs, now } }];
}
const healthStatus = $input.first()?.json?.status ?? 'error';
const healthOk = healthStatus === 'ok';
const mockWf = $input.first()?.json?.mockWorkflowCount;
const mockExec = $input.first()?.json?.mockExecutionCount;
const workflowCount = typeof mockWf === 'number' ? mockWf : 1;
const executionCount = typeof mockExec === 'number' ? mockExec : 0;
const disk = $input.first()?.json?.mockDisk ?? '43% used (placeholder)';
const cronStatus = $input.first()?.json?.mockCronStatus ?? 'hermes cron active (placeholder)';
return [{ json: { healthStatus, healthOk, workflowCount, executionCount, disk, cronStatus, skipAlert: false, checkedAt: new Date().toISOString() } }];
